// === SOV — X Engagement Refresh (This Week: manual full / Thursday hourly batches) ===
// Tweets are scraped within ~24h of posting, when engagement is still near zero.
// This job runs DAILY and, for ATTRIBUTED tweets crossing 7 days of age
// (createdAt in [now-8d, now-7d)), re-scrapes CURRENT engagement via
// apidojo/tweet-scraper (by status URL), updates like/reply/repost/quote/view
// counts, and recomputes post_weight with the mindshare X model (engagement-only
// reach; own vs external tier read from the stored authorWeight marker). Each
// tweet is finalized once, after its first full week. 50 URLs per Apify call.
const helpers = this.helpers;
const KEY = '<REDACTED_SUPABASE_JWT>';
const BASE = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const APIFY_TOKEN = '<REDACTED_APIFY_TOKEN>';
// apidojo~tweet-scraper began FORBIDDING single-tweet URL fetches (runs 'succeed'
// with 0 items) — switched 2026-07-30 to the maker's designated replacement for
// single tweets. Same output schema; $0.05 per tweet URL.
const ACTOR = 'apidojo~twitter-scraper-lite';

const cfgRows = await helpers.httpRequest({ method:'GET', url: BASE + '/sov_config?select=config&id=eq.1', headers: H, json: true });
const cfg = (cfgRows && cfgRows[0] && cfgRows[0].config) || {};
const ew = (cfg.engagementWeights && cfg.engagementWeights.X) || { like:1, reply:2, repost:10, quote:4 };
const clamp = cfg.sentimentClamp || { min:0.5, max:1.3 };
const AB = cfg.authorBaseline || { company:1, employee:2, external:5 };
const AEM = cfg.authorEngMult || { company:1, employee:1.2, external:2 };
const hlX = (cfg.halfLifeDays && cfg.halfLifeDays.X) || 7;
function num(x,d){ return (x!=null?Number(x):d); }
function round6(x){ return parseFloat(Number(x).toFixed(6)); }
function sentMult(s){ if(s==null) return 1.0; const x=Math.max(-3,Math.min(3,Number(s))); return clamp.min + ((x+3)/6)*(clamp.max-clamp.min); }
function ageDays(t){ if(!t) return 0; const d=new Date(t); return isNaN(d)?0:Math.max(0,(Date.now()-d.getTime())/86400000); }
function decay(age,hl){ return age<=7 ? 1 : Math.pow(2, -age/hl); }
// Modes:
//  - MANUAL (UI Execute): original pre-OKR behavior — refresh EVERY attributed
//    post from the last 8 days in one shot.
//  - SCHEDULED (Thursday batches): refresh the PAST WEEK in six hourly batches
//    (04:xx-09:xx). Window is [now-7d, now-24h] — the last 24h are excluded
//    because those posts were first scraped this same morning (no point
//    re-scraping engagement hours after the initial scrape). Each run owns a
//    stable sixth of the ids (id % 6 == hour slot), so the six runs partition
//    the cohort without dup/skip even as the eligible set shifts mid-morning.
let MODE = 'trigger';
try { MODE = ($execution && $execution.mode) || 'trigger'; } catch (e) { /* runner without $execution */ }
const scheduled = MODE !== 'manual';
const SLOTS = 6;
const SLOT = Math.min(SLOTS - 1, Math.max(0, new Date().getHours() - 4));
const now = Date.now();
const from = new Date(now - (scheduled ? 7 : 8)*86400000).toISOString();
const to = new Date(now - (scheduled ? 1 : 0)*86400000).toISOString();
let url = BASE + '/tweets?select=id,url,twitterUrl,companyName,sentiment,createdAt,authorWeight&companyName=not.is.null&companyName=neq.NONE&createdAt=gte.' + encodeURIComponent(from) + '&order=id&limit=200';
if (scheduled) url += '&createdAt=lt.' + encodeURIComponent(to);
const rows = await helpers.httpRequest({ method:'GET', url: url, headers: H, json: true });
let list = Array.isArray(rows) ? rows : [];
if (scheduled) list = list.filter(function (r) { try { return Number(BigInt(String(r.id)) % BigInt(SLOTS)) === SLOT; } catch (e) { return SLOT === 0; } });
if (!list.length) return [{ json: { xEngagementRefresh:true, mode: MODE, slot: scheduled ? SLOT : null, window:[from,to], found:0, scraped:0, updated:0 } }];
const byId = {}; const urls = [];
for (const r of list) { const id = String(r.id); byId[id] = r; urls.push(r.twitterUrl || r.url || ('https://x.com/i/status/' + id)); }
let scraped=0, updated=0; const failed=[];
for (let i=0; i<urls.length; i+=50) {
  const chunk = urls.slice(i, i+50);
  let items = [];
  try {
    items = await helpers.httpRequest({ method:'POST', url:'https://api.apify.com/v2/acts/' + ACTOR + '/run-sync-get-dataset-items?token=' + APIFY_TOKEN, headers:{'Content-Type':'application/json'}, body:{ startUrls: chunk, maxItems: chunk.length }, json:true, timeout:240000 });
  } catch(e){ continue; }
  for (const it of (Array.isArray(items)?items:[])) {
    const pid = String(it.id || it.tweetId || it.rest_id || '');
    const row = byId[pid]; if(!row) continue;
    const like = it.likeCount, rep = it.retweetCount, rpl = it.replyCount, qt = it.quoteCount, vw = (it.viewCount!=null?it.viewCount:it.views);
    if (like==null && rep==null && rpl==null && qt==null) continue;
    scraped++;
    const eng = num(ew.like,1)*Number(like||0) + num(ew.reply,2)*Number(rpl||0) + num(ew.repost,10)*Number(rep||0) + num(ew.quote,4)*Number(qt||0);
    const reach = Math.pow(Math.max(0,eng), 49/50);
    const own = (Number(row.authorWeight)||5) <= 1;
    const B = own ? num(AB.company,1) : num(AB.external,5);
    const M = own ? num(AEM.company,1) : num(AEM.external,2);
    const pw = round6((B + reach*M) * sentMult(row.sentiment) * decay(ageDays(row.createdAt), hlX));
    const body = { likeCount:Number(like||0), retweetCount:Number(rep||0), replyCount:Number(rpl||0), quoteCount:Number(qt||0), post_weight: pw };
    if (vw != null) body.viewCount = Number(vw);
    try {
      await helpers.httpRequest({ method:'PATCH', url: BASE + '/tweets?id=eq.' + encodeURIComponent(pid), headers: Object.assign({}, H, {'Content-Type':'application/json', Prefer:'return=minimal'}), body, json:true });
      updated++;
    } catch(e){ failed.push(pid); }
  }
}
return [{ json: { xEngagementRefresh:true, mode: MODE, slot: scheduled ? SLOT : null, window:[from,to], found:list.length, scraped, updated, failed } }];
